// This file is generated by AI.

// 统一选项卡模型。
//
// 编辑器的选项卡栏是**一个有序序列**, 混合了各类内容: 场景/文件、文本预处理、
// 差异比较、使用说明。它们共享同一套排布与拖拽排序规则, 因此这里用单一的
// 标签联合 (tagged union) 描述, 而不是多套平行数组 + 多个 activeId ——
// 后者既无法乱序排布, 也无法避免"多个选项卡同时处于选中态"这类自相矛盾的状态。
//
// 图标由**选项卡自身携带**: 控件只负责渲染, 不维护"种类 -> 图标"的映射表
// (那种映射表会在新增种类时因为忘记登记而丢图标)。

import {
  ArrowSwapRegular,
  BookQuestionMarkRegular,
  DocumentRegular,
  DocumentTextRegular,
  MicRegular,
  WrenchRegular,
} from '@fluentui/react-icons';
import type { ReactNode } from 'react';

/** 选项卡种类 */
export type TabKind = 'scene' | 'resource' | 'config' | 'novel' | 'diff' | 'voice-workbench' | 'guidance';

export type ResourceKind = 'image' | 'audio' | 'video' | 'text';

/** 差异来源 */
export type DiffKind = 'staged' | 'unstaged' | 'commit';

interface TabBase {
  /** 全局唯一 id (同时作为 React key 与排序单位) */
  id: string;
  kind: TabKind;
  /** 选项卡标题 */
  title: string;
  /** 悬浮提示 (通常为完整路径或补充说明) */
  tooltip: string;
  /** 标题左侧的图标 */
  icon?: ReactNode;
}

/** 场景/文件编辑选项卡 */
export interface SceneTab extends TabBase {
  kind: 'scene';
  /** 绝对路径 (与 `documents[].path` 一致) */
  path: string;
}

/** 资源选项卡: 文本资源复用 CodeEditor, 媒体资源显示专用控件。 */
export interface ResourceTab extends TabBase {
  kind: 'resource';
  path: string;
  resourceKind: ResourceKind;
}

/**
 * 游戏配置选项卡 (`game/config.txt`)。
 *
 * 单独成为一种选项卡而不是当成普通文本资源: 它是**项目的配置**而不是一份素材, 与
 * 资源浏览器里点开的 txt 不是一回事 —— 标题图标不同才能一眼认出"这条是配置"。
 * 渲染仍然复用 Monaco (与文本资源同一条路径)。
 */
export interface ConfigTab extends TabBase {
  kind: 'config';
  path: string;
  resourceKind: 'text';
}

/** 文本预处理选项卡 */
export interface NovelTab extends TabBase {
  kind: 'novel';
}

/** 差异比较选项卡 */
export interface DiffTab extends TabBase {
  kind: 'diff';
  /** 仓库相对路径 (正斜杠) */
  file: string;
  diffKind: DiffKind;
  /** `diffKind` 为 commit 时的提交 id */
  commitId?: string;
}

/** 配音工作台选项卡 (单例) */
export interface WorkbenchTab extends TabBase {
  kind: 'voice-workbench';
}

/** 静态说明页选项卡 (单例) */
export interface GuidanceTab extends TabBase {
  kind: 'guidance';
}

export type WorkbenchTabItem = SceneTab | ResourceTab | ConfigTab | NovelTab | DiffTab | WorkbenchTab | GuidanceTab;

export const WORKBENCH_TAB_ID = 'voice-workbench';
export const VOICE_GUIDE_TAB_ID = 'voice-guide';

/** 场景/文件选项卡的稳定 id */
export function sceneTabId(path: string): string {
  return `scene:${path}`;
}

/** 资源选项卡的稳定 id。 */
export function resourceTabId(path: string): string {
  return `resource:${path}`;
}

/** 游戏配置选项卡的稳定 id (与资源选项卡区分开, 同一个文件两种选项卡不会互相顶掉)。 */
export function configTabId(path: string): string {
  return `config:${path}`;
}

/** 构造场景选项卡 */
export function makeSceneTab(path: string, name: string): SceneTab {
  return {
    id: sceneTabId(path),
    kind: 'scene',
    title: name,
    tooltip: path,
    path,
  };
}

/** 构造资源选项卡。 */
export function makeResourceTab(path: string, name: string, resourceKind: ResourceKind): ResourceTab {
  return {
    id: resourceTabId(path),
    kind: 'resource',
    title: name,
    tooltip: path,
    // 空白页图标: 中间不画内容, 与"带内容的文本页"(文本预处理) 一眼区分
    icon: <DocumentRegular />,
    path,
    resourceKind,
  };
}

/** 构造游戏配置选项卡 (`game/config.txt`)。 */
export function makeConfigTab(path: string, name: string): ConfigTab {
  return {
    id: configTabId(path),
    kind: 'config',
    title: name,
    tooltip: `${path}（项目配置）`,
    icon: <WrenchRegular />,
    path,
    resourceKind: 'text',
  };
}

/** 构造文本预处理选项卡 */
export function makeNovelTab(seq: number): NovelTab {
  return {
    id: `novel-${Date.now().toString(36)}-${seq}`,
    kind: 'novel',
    title: `文本预处理 ${seq}`,
    tooltip: '将小说原文转换为 WebGAL 脚本',
    icon: <DocumentTextRegular />,
  };
}

/** 构造差异比较选项卡 */
export function makeDiffTab(input: { file: string; title: string; diffKind: DiffKind; commitId?: string }): DiffTab {
  return {
    id: `diff:${input.diffKind}:${input.commitId ?? ''}:${input.file}`,
    kind: 'diff',
    title: input.title,
    tooltip: input.file,
    icon: <ArrowSwapRegular />,
    file: input.file,
    diffKind: input.diffKind,
    commitId: input.commitId,
  };
}

/** 构造配音工作台选项卡 */
export function makeWorkbenchTab(): WorkbenchTab {
  return {
    id: WORKBENCH_TAB_ID,
    kind: 'voice-workbench',
    title: '配音工作台',
    tooltip: 'GPT-SoVITS 配音服务、角色库与任务队列',
    icon: <MicRegular />,
  };
}

/** 构造配音使用说明选项卡 */
export function makeVoiceGuideTab(): GuidanceTab {
  return {
    id: VOICE_GUIDE_TAB_ID,
    kind: 'guidance',
    title: '配音使用说明',
    tooltip: '配音工作流的操作与交互约定',
    icon: <BookQuestionMarkRegular />,
  };
}
